'use strict';
(async()=>{const out=document.querySelector('#verification-result');const id=new URL(location.href).searchParams.get('id');if(!id||!/^[A-Za-z0-9_-]{20,100}$/.test(id)){out.textContent='Référence de vérification invalide.';return}try{const r=await fetch('/api/public/attestations/'+encodeURIComponent(id),{credentials:'omit',cache:'no-store',redirect:'error'});if(!r.ok)throw Error('Vérification indisponible ou attestation introuvable.');const data=await r.json();for(const [label,key] of [['Émetteur','issuer'],['Attestation','attestation_id'],['Date','date'],['Statut','status']]){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=({valid:'Valide',expired:'Expirée',revoked:'Révoquée',replaced:'Remplacée'})[data[key]]||data[key];out.append(dt,dd)}}catch(e){out.textContent=e.message}})();
